/**
 * components/FeatureImportance.js
 * Two-panel card: SHAP feature bars (left) + Attention key days (right)
 */

import React from 'react';
import './FeatureImportance.css';

/* ── SHAP PANEL ──────────────────────────────────────── */
function ShapPanel({ features }) {
  const maxAbs = Math.max(...features.map(f => Math.abs(f.impact)), 0.0001);

  return (
    <div className="fi-card">
      <div className="fi-hdr">
        <div className="fi-ico cyan">🔑</div>
        <div className="fi-title">SHAP Feature Importance</div>
      </div>
      <div className="fi-sub">
        Contribution of each technical indicator to this prediction
      </div>

      {features.map((f, i) => {
        const pos  = f.impact >= 0;
        const pct  = (Math.abs(f.impact) / maxAbs) * 100;
        return (
          <div key={i} className="shap-item">
            <div className="shap-row">
              <span className="shap-name">{f.name}</span>
              <span className={`shap-tag ${pos ? 'tag-pos' : 'tag-neg'}`}>
                {pos ? '↗ Bullish' : '↘ Bearish'}
              </span>
            </div>
            <div className="shap-track">
              <div
                className={pos ? 'shap-fill-pos' : 'shap-fill-neg'}
                style={{ width: `${pct}%` }}
              />
            </div>
            <div className="shap-val" style={{ color: pos ? 'var(--green)' : 'var(--red)' }}>
              {f.impact >= 0 ? '+' : ''}{f.impact.toFixed(5)}&nbsp;SHAP impact
            </div>
          </div>
        );
      })}

      <div className="fi-tip">
        💡 Positive = pushes price UP · Negative = pushes price DOWN
      </div>
    </div>
  );
}

/* ── ATTENTION PANEL ─────────────────────────────────── */
function AttentionPanel({ days }) {
  const maxImp = Math.max(...days.map(d => d.importance), 0.0001);

  return (
    <div className="fi-card">
      <div className="fi-hdr">
        <div className="fi-ico purple">👁️</div>
        <div className="fi-title">Attention — Key Historical Days</div>
      </div>
      <div className="fi-sub">
        Days the LSTM model focused on most (60-day window)
      </div>

      {days.map((d, i) => (
        <div key={i} className="attn-item">
          <span className="attn-rank">#{i + 1}</span>
          <span className="attn-lbl">
            {d.days_ago === 0 ? 'Today' : `${d.days_ago}d ago`}
          </span>
          <div className="attn-track">
            <div
              className="attn-fill"
              style={{ width: `${(d.importance / maxImp) * 100}%` }}
            />
          </div>
          <span className="attn-val">{d.importance.toFixed(3)}</span>
        </div>
      ))}

      <div className="fi-tip">
        💡 Higher importance = the model paid more attention to that day when predicting
      </div>
    </div>
  );
}

/* ── EXPORT ──────────────────────────────────────────── */
export default function FeatureImportance({ topFeatures, importantDays }) {
  return (
    <div className="fi-grid">
      <ShapPanel   features={topFeatures}  />
      <AttentionPanel days={importantDays} />
    </div>
  );
}
